            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Newton", Text = "But if I have done the public any service this way, 'tis due to nothing but industry and a patient thought.", Author = "Isaac Newton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Newton", Text = "It is inconceivable that inanimate brute matter should, without the mediation of something else which is not material, operate upon and affect other matter without mutual contact, as it must be, if gravitation in the sense of Epicurus, be essential and inherent in it.", Author = "Isaac Newton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Newton", Text = "Gravity must be caused by an agent acting constantly according to certain laws; but whether this agent be material or immaterial, I have left open to the consideration of my readers.", Author = "Isaac Newton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Newton", Text = "The 2300 years do not end before the year 2132 nor after 2370. The time times & half time do not end before 2060. .... It may end later, but I see no reason for its ending sooner.", Author = "Isaac Newton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Newton", Text = "This I mention not to assert when the time of the end shall be, but to put a stop to the rash conjectures of fancifull men who are frequently predicting the time of the end, & by doing so bring the sacred prophesies into discredit as often as their predictions fail.", Author = "Isaac Newton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Newton", Text = "It's much better to do a little with certainty, & leave the rest for others that come after you, than to explain all things by conjecture without making sure of any thing.", Author = "Isaac Newton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Newton", Text = "In the beginning of the year 1665 I found the method of approximating Series and the Rule for reducing any dignity of any Binomial into such a series.", Author = "Isaac Newton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Newton", Text = "All this was in the two plague years of 1665 and 1666, for in those days I was in the prime of my age for invention, and minded Mathematicks and Philosophy more than at any time since.", Author = "Isaac Newton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Newton", Text = "I do not know what I may appear to the world, but to myself I seem to have been only like a boy playing on the sea-shore, and diverting myself in now and then finding a smoother pebble or a prettier shell than ordinary, whilst the great ocean of truth lay all undiscovered before me.", Author = "Isaac Newton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Newton", Text = "In default of any other proof, the thumb would convince me of the existence of a God.", Author = "Isaac Newton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Newton", Text = "We account the Scriptures of God to be the most sublime philosophy. I find more sure remarks of authenticity in the Bible than in any profane history whatever.", Author = "Isaac Newton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Newton", Text = "Oh, Diamond! Diamond! thou little knowest what mischief thou hast done!", Author = "Isaac Newton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Newton", Text = "It is the perfection of God's works that they are all done with the greatest simplicity. He is the God of order and not of confusion.", Author = "Isaac Newton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Newton", Text = "God created everything by number, weight and measure.", Author = "Isaac Newton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Newton", Text = "The ancients considered mechanics in a twofold respect; as rational, which proceeds accurately by demonstration, and practical.", Author = "Isaac Newton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Newton", Text = "But the errors are not in the art, but in the artificers.", Author = "Isaac Newton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Newton", Text = "Geometry does not teach us to draw these lines, but requires them to be drawn; for it requires that the learner should first be taught to describe these accurately, before he enters upon geometry; then it shows how by these operations problems may be solved.", Author = "Isaac Newton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Newton", Text = "Rational mechanics must be the science of the motions which result from any forces, and of the forces which are required for any motions, accurately propounded and demonstrated.", Author = "Isaac Newton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Newton", Text = "I do not define time, space, place, and motion, as being well known to all.", Author = "Isaac Newton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Newton", Text = "We are to admit no more causes of natural things than such as are both true and sufficient to explain their appearances.", Author = "Isaac Newton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Newton", Text = "Every body continues in state of rest, or of uniform motion in a right line, unless it is compelled to change that state by forces impressed upon it.", Author = "Isaac Newton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Newton", Text = "To every action there is always opposed an equal reaction; or, the mutual actions of two bodies upon each other are always equal, and directed to contrary parts.", Author = "Isaac Newton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Newton", Text = "I frame no hypotheses.", Author = "Isaac Newton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Newton", Text = "For whatever is not deduced from the phenomena must be called a hypothesis; and hypotheses, whether metaphysical or physical, or based on occult qualities, or mechanical, have no place in experimental philosophy.", Author = "Isaac Newton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Newton", Text = "This most beautiful System of the Sun, Planets and Comets, could only proceed from the counsel and dominion of an intelligent and powerful being.", Author = "Isaac Newton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Newton", Text = "And lest the systems of the fixed Stars should, by their gravity, fall on each other mutually, he hath placed those Systems at immense distances one from another.", Author = "Isaac Newton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Newton", Text = "This Being governs all things, not as the soul of the world, but as Lord over all: And on account of his dominion he is wont to be called Lord God παντοκρáτωρ or Universal Ruler.", Author = "Isaac Newton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Newton", Text = "The supreme God is a Being eternal, infinite, absolutely perfect; but a being, however perfect, without dominion, cannot be said to be Lord God.", Author = "Isaac Newton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Newton", Text = "He is Eternal and Infinite, Omnipotent and Omniscient; that is, his duration reaches from Eternity to Eternity; his presence from Infinity to Infinity; he governs all things, and knows all things that are or can be done.", Author = "Isaac Newton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Newton", Text = "He is not Eternity or Infinity, but Eternal and Infinite; he is not Duration or Space, but he endures and is present.", Author = "Isaac Newton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Newton", Text = "He endures for ever, and is every where present; and by existing always and every where, he constitutes Duration and Space.", Author = "Isaac Newton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Newton", Text = "Every soul that has perception is, though in different times and in different organs of sense and motion, still the same indivisible person.", Author = "Isaac Newton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Newton", Text = "God is the same God, always and every where. He is omnipresent, not virtually only, but also substantially; for virtue cannot subsist without substance.", Author = "Isaac Newton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Newton", Text = "In him are all things contained and moved; yet neither affects the other: God suffers nothing from the motion of bodies; bodies find no resistance from the omnipresence of God.", Author = "Isaac Newton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Newton", Text = "It's allowed by all that the supreme God exists necessarily; and by the same necessity he exists always and every where.", Author = "Isaac Newton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Newton", Text = "Whence also he is all similar, all eye, all ear, all brain, all arm, all power to perceive, to understand, and to act; but in a manner not at all human, in a manner not at all corporeal, in a manner utterly unknown to us.", Author = "Isaac Newton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Newton", Text = "As a blind man has no idea of colours, so have we no idea of the manner by which the all-wise God perceives and understands all things.", Author = "Isaac Newton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Newton", Text = "He is utterly void of all body and bodily figure, and can therefore neither be seen, nor heard, nor touched; nor ought to be worshipped under the representation of any corporeal thing.", Author = "Isaac Newton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Newton", Text = "We have ideas of his attributes, but what the real substance of any thing is, we know not.", Author = "Isaac Newton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Newton", Text = "We know him only by his most wise and excellent contrivances of things, and final causes; we admire him for his perfections; but we reverence and adore him on account of his dominion.", Author = "Isaac Newton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Newton", Text = "For we adore him as his servants; and a God without dominion, providence, and final causes, is nothing else but Fate and Nature.", Author = "Isaac Newton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Newton", Text = "Blind metaphysical necessity, which is certainly the same always and every where, could produce no variety of things.", Author = "Isaac Newton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Newton", Text = "All that diversity of natural things which we find, suited to different times and places, could arise from nothing but the ideas and will of a Being necessarily existing.", Author = "Isaac Newton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Newton", Text = "Are not the Rays of Light in passing by the edges and sides of Bodies, bent several times backwards and forwards, with a motion like that of an Eel?", Author = "Isaac Newton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Newton", Text = "Do not Bodies and Light act mutually upon one another; that is to say, Bodies upon Light in emitting, reflecting, refracting and inflecting it, and Light upon Bodies for heating them, and putting their parts into a vibrating motion wherein heat consists?", Author = "Isaac Newton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Newton", Text = "Do not several sorts of Rays make Vibrations of several bignesses, which according to their bigness excite Sensations of several Colours, much after the manner that the Vibrations of the Air, according to their several bignesses excite Sensations of several Sounds?", Author = "Isaac Newton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Newton", Text = "Is not the Heat of the warm Room convey'd through the Vacuum by the Vibrations of a much subtiler Medium than Air, which after the Air was drawn out remained in the Vacuum?", Author = "Isaac Newton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Newton", Text = "And is not this Medium the same with that Medium by which Light is refracted and reflected and by whose Vibrations Light communicates Heat to Bodies, and is put into Fits of easy Reflexion and easy Transmission?", Author = "Isaac Newton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Newton", Text = "And do not hot Bodies communicate their Heat to contiguous cold ones, by the Vibrations of this Medium propagated from them into the cold ones?", Author = "Isaac Newton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Newton", Text = "And is not this Medium exceedingly more rare and subtile than the Air, and exceedingly more elastick and active?", Author = "Isaac Newton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Newton", Text = "And doth it not readily pervade all Bodies? And is it not (by its elastick force) expanded through all the Heavens?", Author = "Isaac Newton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Newton", Text = "Doth not this Æthereal Medium in passing out of Water, Glass, Crystal, and other compact and dense Bodies into empty Spaces, grow denser and denser by degrees, and by that means refract the Rays of Light not in a point, but by bending them gradually in curve Lines?", Author = "Isaac Newton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Newton", Text = "And doth not the gradual condensation of this Medium extend to some distance from the Bodies, and thereby cause the Inflexions of the Rays of Light, which pass by the edges of dense Bodies, at some distance from the Bodies?", Author = "Isaac Newton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Newton", Text = "Is not this Medium [æther] much rarer within the dense Bodies of the Sun, Stars, Planets, and Comets, than in the empty celestial Spaces between them?", Author = "Isaac Newton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Newton", Text = "And in passing from them to great distances, doth it not grow denser and denser perpetually, and thereby cause the gravity of those great Bodies towards one another, and of their parts towards the Bodies; every Body endeavouring to go from the denser parts of the Medium towards the rarer?", Author = "Isaac Newton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Newton", Text = "And though this Increase of density may at great distances be exceeding stow, yet if the elastick force of this Medium be exceeding great, it may suffice to impel Bodies from the denser parts of the Medium towards the rarer, with all that power which we call Gravity.", Author = "Isaac Newton" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Newton", Text = "And that the elastic force of this Medium is exceeding great, may be gather'd from the swiftness of its Vibrations.", Author = "Isaac Newton" },
